// Verus program: interleave three equal-length vectors index-by-index.
//
// For each i in [0, n):
//   res[3*i]   = s1[i]
//   res[3*i+1] = s2[i]
//   res[3*i+2] = s3[i]
// So |res| = 3*n.
//
// Assumption: 0 <= 3*n <= i32::MAX (given). We also need it to fit in `usize`
// to allocate the output vector; on typical targets this holds automatically,
// and the i32::MAX bound is far smaller than usize::MAX.

#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> (res: Vec<i32>)
    requires
        s1.len() == s2.len(),
        s2.len() == s3.len(),
        // Problem statement bound (expressed in `int` for specs):
        0 <= 3 * (s1.len() as int),
        3 * (s1.len() as int) <= i32::MAX as int,
    ensures
        res.len() == 3 * s1.len(),
        forall|i: int| 0 <= i < s1.len() ==> res[3*i] == s1[i],
        forall|i: int| 0 <= i < s1.len() ==> res[3*i + 1] == s2[i],
        forall|i: int| 0 <= i < s1.len() ==> res[3*i + 2] == s3[i],
{
    let n: usize = s1.len();
    let mut out: Vec<i32> = Vec::with_capacity(3 * n);

    let mut i: usize = 0;
    while i < n
        invariant
            i <= n,
            s1.len() == n,
            s2.len() == n,
            s3.len() == n,
            out.len() == 3 * i,
            // All completed triplets are correctly placed.
            forall|j: int| 0 <= j < i ==> out[3*j] == s1[j],
            forall|j: int| 0 <= j < i ==> out[3*j + 1] == s2[j],
            forall|j: int| 0 <= j < i ==> out[3*j + 2] == s3[j],
    {
        out.push(s1[i]);
        out.push(s2[i]);
        out.push(s3[i]);
        i = i + 1;
    }

    out
}

} // verus!